update task_management
project_id = #{projectId}, title = #{title}, description = #{description}, priority = #{priority}, task_type = #{taskType}, status = #{status}, remark = #{remark}, template_id = #{templateId}, update_by = #{updateBy}, overall_score = #{overallScore}, compliance_rate = #{complianceRate}, passed_file_count = #{passedFileCount}, total_file_count = #{totalFileCount}, update_time = sysdate()
where id = #{id}

