SELECT DATE_FORMAT(create_time, '%Y') as year, COUNT(*) as count, task_type as type FROM task_management WHERE del_flag = '0'
AND DATE_FORMAT(create_time, '%Y') BETWEEN #{startYear} AND #{endYear}
GROUP BY DATE_FORMAT(create_time, '%Y'), task_type ORDER BY year ASC, task_type ASC

SELECT DATE_FORMAT(create_time, '%Y-%m') AS month, AVG(overall_score) AS overallScore FROM task_management
del_flag = '0' AND status = 'completed'
AND DATE_FORMAT(create_time, '%Y-%m') BETWEEN #{startMonth} AND #{endMonth}
AND DATE_FORMAT(create_time, '%Y-%m') >= #{startMonth}
AND DATE_FORMAT(create_time, '%Y-%m') <= #{endMonth}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month ASC

SELECT DATE_FORMAT(create_time, '%Y') AS year, AVG(overall_score) AS overallScore FROM task_management
del_flag = '0' AND status = 'completed'
AND DATE_FORMAT(create_time, '%Y') BETWEEN #{startYear} AND #{endYear}
AND DATE_FORMAT(create_time, '%Y') >= #{startYear}
AND DATE_FORMAT(create_time, '%Y') <= #{endYear}
GROUP BY DATE_FORMAT(create_time, '%Y') ORDER BY year ASC
